class Solution {
public:
    vector<bool> transformStr(string s,vector<string>& strs) {
        int n=s.size(),ones=count(s.begin(),s.end(),'1');
        vector<int> pref(n+1);
        for(int i=0;i<n;i++)pref[i+1]=pref[i]+(s[i]=='1');
        vector<bool> ans;
        for(const string &t:strs){
            int fixed=0,wild=0;
            for(char c:t){fixed+=c=='1';wild+=c=='?';}
            int need=ones-fixed;
            if(need<0||need>wild){ans.push_back(false);continue;}
            int remaining=wild,cur=0;bool good=true;
            for(int i=0;i<n;i++){
                if(t[i]=='1')cur++;
                if(t[i]=='?'){
                    if(remaining<=need){cur++;need--;}
                    remaining--;
                }
                if(cur>pref[i+1]){good=false;break;}
            }
            ans.push_back(good);
        }
        return ans;
    }
};
